<section class="page-hero shell compact"><p class="kicker">Purchase history</p><h1>Your orders.</h1><p>Every order keeps an immutable snapshot of what you bought and what you paid.</p></section><section class="section section-tight shell account-grid"><?php include __DIR__.'/_nav.php'; ?><div class="account-main"><?php if(!$orders):?><div class="empty-state"><h2>No orders yet.</h2><a class="btn dark" href="<?=e(url('/shop'))?>">Explore collection</a></div><?php else:?><div class="order-list"><?php foreach($orders as $o):?><a class="order-row large" href="<?=e(url('/account/orders/'.$o['guid']))?>"><div><strong><?=e($o['number'])?></strong><small><?=e(date('d M Y, H:i',strtotime($o['created_at'])))?> · <?=count($o['items'])?> item(s)</small></div><span class="status-pill commerce <?=e(strtolower($o['status']))?>"><?=e(str_replace('_',' ',$o['status']))?></span><b><?=money($o['pricing']['grand_total'])?></b></a><?php endforeach;?></div><?php endif;?></div></section>
